import java.util.Scanner;

public class Main {
    static long inf = 17446744073709551616L;
    static long[][] d = new long[18][250005];
    static long[] f = new long[250005], inv_f = new long[250005];
    static long N, K, m;

    static long q_pow(long a, long b) {
        long res = 1L, base = a;
        while (b > 0) {
            if ((b & 1L) == 1L) res = (res * base) % m;
            base = (base * base) % m;
            b >>= 1;
        }
        return res;
    }

    static long comb(int a, int b) {
        return (((f[a] * inv_f[b]) % m) * inv_f[a - b]) % m;
    }

    static long compute_result() {
        int i, j, l;
        f[0] = 1L;
        for (i = 1; i <= N; i++) {
            f[i] = (f[i - 1] * i) % m;
        }
        inv_f[(int) N] = q_pow(f[(int) N], m - 2);
        for (i = (int) N - 1; i >= 0; i--) {
            inv_f[i] = (inv_f[i + 1] * (i + 1)) % m;
        }
        for (i = 1; i <= N; i++) {
            d[1][i] = inv_f[i];
