                d[i][j] %= m;
            }
            res += d[i][(int) N] * comb((int) K, i);
            res %= m;
        }
        res = (res * f[(int) N]) % m;
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextLong();
